const p = $json.body || {};
const { userId, conversationId, messageId, userMessage, baseUrl, mode: rawMode, maxItems: rawMax, currentDraft: rawDraft, draftBooks: rawBooks } = p;
if (!userId || !conversationId || !messageId || !userMessage) throw new Error('Missing required fields');
const mode = rawMode === 'playlist_builder' ? 'playlist_builder' : 'chat';
const maxItems = mode === 'playlist_builder' ? Math.max(3, Math.min(20, Number(rawMax) || 8)) : null;
const isFirstMessage = p.isFirstMessage !== false && p.isFirstMessage !== 'false';
let currentDraft = null;
if (mode === 'playlist_builder' && rawDraft?.items?.length) {
  const items = rawDraft.items.filter(it => Number.isFinite(Number(it?.catalogBookId)) && Number(it.catalogBookId) > 0).map((it, i) => ({ catalogBookId: Number(it.catalogBookId), position: i + 1, note: it.note || null }));
  if (items.length) currentDraft = { title: rawDraft.title || null, description: rawDraft.description || null, items };
}
const draftBooks = Array.isArray(rawBooks) ? rawBooks.filter(b => Number.isFinite(Number(b?.id))).map(b => ({ id: Number(b.id), title: b.title || '', author: b.author || '' })) : [];
const isPlaylistBuilder = mode === 'playlist_builder';
const hasCurrentDraft = !!(currentDraft?.items?.length);
const draftCtx = hasCurrentDraft ? `\n\nBORRADOR ACTUAL (${currentDraft.items.length} libros, IDs: [${currentDraft.items.map(i=>i.catalogBookId).join(',')}]):\n${JSON.stringify(currentDraft)}` : '';
const booksCtx = draftBooks.length ? `\n\nLIBROS DEL BORRADOR:\n${JSON.stringify(draftBooks.map(b=>({id:b.id,title:b.title})))}` : '';
const agentInput = `userId: ${userId}\nconversationId: ${conversationId}\nmessageId: ${messageId}\nmode: ${mode}${maxItems ? '\nmaxItems: '+maxItems : ''}\nbaseUrl: ${baseUrl||'http://localhost:4200'}\n\nMENSAJE: "${userMessage}"${draftCtx}${booksCtx}`;
const agentInputFinal = agentInput + '\n\n⚠️ Llama search_catalog_books(query="texto", limit=8). Si devuelve 0 resultados relevantes, llama search_external_books(query="texto", limit=5). Produce la respuesta JSON al final.';
return { userId, conversationId, messageId, userMessage, baseUrl: baseUrl||'http://localhost:4200', mode, maxItems, currentDraft, draftBooks, isPlaylistBuilder, hasCurrentDraft, isFirstMessage, agentInput: agentInputFinal, startTime: Date.now() };

const extractData = $('Extraer URLs del Agent').item.json;
const prev = $('Normalizar Payload').item.json;
const agentOutput = extractData.agentOutput || '';
let agentParsed = extractData.agentParsed || {};

// Normalize: if agent returned playlistDraft structure at root level, wrap it
if (prev.isPlaylistBuilder && !agentParsed.playlistDraft && Array.isArray(agentParsed.items) && agentParsed.items.some(it => it?.catalogBookId)) {
  agentParsed = {
    response: agentParsed.response || '',
    bookIds: agentParsed.bookIds || [],
    suggestedTitle: agentParsed.suggestedTitle || agentParsed.title || null,
    playlistDraft: { title: agentParsed.title || 'Mi playlist', description: agentParsed.description || '', items: agentParsed.items }
  };
}

// 1. bookIds
const seen = new Set();
const bookIds = [];
if (extractData.correctBookIds?.length > 0) {
  for (const id of extractData.correctBookIds) { if (!seen.has(id)) { seen.add(id); bookIds.push(id); } }
} else {
  let rawFound = $input.item.json.found_books;
  if (typeof rawFound === 'string') { try { rawFound = JSON.parse(rawFound); } catch { rawFound = []; } }
  const arr = Array.isArray(rawFound) ? rawFound : [];
  for (const b of arr) { const id = Number(b?.id); if (Number.isFinite(id) && id > 0 && !seen.has(id)) { seen.add(id); bookIds.push(id); } }
}

// 2. Response text
let booksArr = [];
for (const key of Object.keys(agentParsed)) {
  const val = agentParsed[key];
  if (Array.isArray(val) && val.length > 0 && val[0] && typeof val[0] === 'object' && (val[0].title || val[0].coverUrl)) { booksArr = val; break; }
}
let responseText = agentParsed.response || '';
if (!responseText && booksArr.length > 0) {
  responseText = booksArr.map((r, i) => `${i+1}. **${r.title || ''}** — *${r.author || ''}*: ${(r.description || '').slice(0, 150)}`).join('\n\n');
}
if (!responseText) responseText = agentOutput;

// 3. Playlist
let playlistDraft = null;
if (prev.isPlaylistBuilder && !agentParsed.playlistDraft && bookIds.length > 0) {
  const agentTitle = agentParsed.playlistTitle || agentParsed.title || null;
  playlistDraft = { title: agentTitle || 'Mi playlist', description: agentParsed.description || '', items: bookIds.map((id, i) => ({ catalogBookId: id, position: i+1, note: null })) };
  if (!responseText || responseText === agentOutput) responseText = `He creado una playlist con ${bookIds.length} libro${bookIds.length !== 1 ? 's' : ''} seleccionados. ¿Cambiamos algo?`;
}
if (prev.isPlaylistBuilder && agentParsed.playlistDraft) {
  const rd = agentParsed.playlistDraft;
  const items = []; const s2 = new Set();
  for (const it of (rd.items || [])) { const id = Number(it?.catalogBookId); if (!Number.isFinite(id) || id <= 0 || s2.has(id)) continue; s2.add(id); items.push({ catalogBookId: id, position: items.length+1, note: it.note||null }); }
  playlistDraft = { title: rd.title || 'Mi playlist', description: rd.description || '', items };
  if (prev.hasCurrentDraft && prev.currentDraft) {
    const cur = prev.currentDraft;
    const curIds = new Set(cur.items.map(i => Number(i.catalogBookId)));
    const keptRatio = items.length === 0 ? 0 : items.filter(i => curIds.has(i.catalogBookId)).length / cur.items.length;
    const removeRe = /(quit|elimin|borra|sac[ao]|reemplaz|no me gusta|no quiero|cambi[ao]|sustitu)/i;
    const addOnlyRe = /(añad|agreg|suma|incluye|faltan|completa|amplia)/i;
    const isRemove = removeRe.test(prev.userMessage||'');
    const isAdd = !isRemove && (addOnlyRe.test(prev.userMessage||'') || (/\bmete\b/i.test(prev.userMessage||'') && !isRemove));
    if (isAdd) {
      const rebuilt = cur.items.map((it,i) => ({ catalogBookId: Number(it.catalogBookId), position: i+1, note: it.note||null }));
      const inR = new Set(rebuilt.map(i=>i.catalogBookId));
      for (const ni of items) { if (!inR.has(ni.catalogBookId)) { rebuilt.push({...ni, position: rebuilt.length+1}); inR.add(ni.catalogBookId); } }
      playlistDraft.items = rebuilt;
      if (!playlistDraft.title || playlistDraft.title==='Mi playlist') playlistDraft.title = cur.title || 'Mi playlist';
    } else if (keptRatio < 0.4 && items.length < Math.ceil(cur.items.length * 0.6)) {
      playlistDraft.items = cur.items.map((it,i) => ({ catalogBookId: Number(it.catalogBookId), position: i+1, note: it.note||null }));
      playlistDraft.title = cur.title || playlistDraft.title;
    }
    const finalIds = [...new Set(playlistDraft.items.map(i=>i.catalogBookId))];
    bookIds.length = 0; finalIds.forEach(id => bookIds.push(id));
  }
  if (!responseText || responseText === agentOutput) responseText = `Playlist actualizada con ${playlistDraft.items.length} libros. ¿Cambiamos algo más?`;
}

// 4. Conversation title (solo para el primer mensaje)
let conversationTitle = null;
if (prev.isFirstMessage) {
// 4a. Agent suggested title (only when agent returns valid JSON)
const rawAgentTitle = agentParsed.suggestedTitle;
if (rawAgentTitle && typeof rawAgentTitle === 'string') {
  const t = rawAgentTitle.trim().replace(/[.…?!]+$/, '').slice(0, 60);
  if (t.length > 2) conversationTitle = t;
}
// 4b. AI-generated title from Generar Título node
if (!conversationTitle) {
  try {
    const titleNode = $('Generar Título').item.json;
    const aiRaw = titleNode?.choices?.[0]?.message?.content?.trim();
    if (aiRaw) {
      const aiTitle = aiRaw.replace(/^["'«»\[\(]|["'«»\]\)]+$/g, '').replace(/[.…]+$/, '').trim().slice(0, 60);
      if (aiTitle.length > 2) conversationTitle = aiTitle;
    }
  } catch {}
}
// 4c. Fallback: user message (cleaned)
if (!conversationTitle && prev.userMessage) {
  conversationTitle = prev.userMessage.trim().replace(/[.…?!]+$/, '').slice(0, 55) || null;
}
} // end isFirstMessage

// 5. Firestore body
const toStrArr = arr => ({ values: (arr || []).map(v => ({ stringValue: String(v) })) });
const toIntArr = arr => ({ values: (arr || []).map(v => Number(v)).filter(n => Number.isFinite(n)).map(n => ({ integerValue: String(Math.trunc(n)) })) });
const mf = {
  thoughts: { arrayValue: toStrArr([]) },
  recommendations: { arrayValue: toIntArr(bookIds) },
  recommendationsCount: { integerValue: String(bookIds.length) },
  used_querys: { arrayValue: toStrArr([]) },
  intentType: { stringValue: 'book_recommendation' },
  processingTime: { integerValue: String(Math.trunc(Number(Date.now() - (prev.startTime || Date.now())) || 0)) },
  mode: { stringValue: prev.mode || 'chat' }
};
if (playlistDraft) {
  mf.playlistDraft = { mapValue: { fields: {
    title: { stringValue: String(playlistDraft.title || '') },
    description: { stringValue: String(playlistDraft.description || '') },
    items: { arrayValue: { values: (playlistDraft.items || []).map(it => ({ mapValue: { fields: {
      catalogBookId: { integerValue: String(Math.trunc(Number(it.catalogBookId))) },
      position: { integerValue: String(Math.trunc(Number(it.position))) },
      ...(it.note ? { note: { stringValue: String(it.note) } } : {})
    } } })) } }
  }}};
}
const firestoreBody = {
  fields: {
    content: { stringValue: responseText },
    status: { stringValue: 'completed' },
    metadata: { mapValue: { fields: mf } }
  }
};
return { userId: prev.userId, conversationId: prev.conversationId, messageId: prev.messageId, content: responseText, conversationTitle, metadata: { recommendations: bookIds, mode: prev.mode || 'chat' }, firestoreBody };

const err = $json;
let userId='', conversationId='', messageId='';
try { const w=$('Webhook').item.json; if(w?.body){userId=w.body.userId||'';conversationId=w.body.conversationId||'';messageId=w.body.messageId||'';} } catch {}
try { const n=$('Normalizar Payload').item.json; userId=userId||n.userId||'';conversationId=conversationId||n.conversationId||'';messageId=messageId||n.messageId||''; } catch {}
return { userId, conversationId, messageId, errorContent: 'Lo siento, ocurrió un error procesando tu mensaje. Por favor inténtalo de nuevo.' };

const agentOutput = $input.item.json.output || '';
let coverUrls = [], correctBookIds = [], agentParsed = {};
try {
  let c = agentOutput.trim();
  if (c.startsWith('```')) c = c.replace(/^```(?:json)?\n?/,'').replace(/\n?```$/,'').trim();
  agentParsed = JSON.parse(c);

  // Case 1: correct format with bookIds array of integers
  if (Array.isArray(agentParsed.bookIds)) {
    correctBookIds = agentParsed.bookIds.map(v => Number(v)).filter(id => Number.isFinite(id) && id > 0);
  }

  // Case 2: agent returned playlistDraft directly at root (has items[].catalogBookId)
  if (correctBookIds.length === 0 && Array.isArray(agentParsed.items)) {
    const catalogIds = agentParsed.items.map(it => Number(it?.catalogBookId)).filter(id => Number.isFinite(id) && id > 0);
    if (catalogIds.length > 0) correctBookIds = catalogIds;
  }

  // Case 3: scan all top-level arrays for objects with coverUrl
  if (correctBookIds.length === 0) {
    const allUrls = new Set();
    for (const key of Object.keys(agentParsed)) {
      const val = agentParsed[key];
      if (Array.isArray(val)) {
        for (const item of val) {
          if (item && typeof item === 'object' && item.coverUrl) allUrls.add(item.coverUrl);
        }
      }
    }
    coverUrls = [...allUrls];
  }
} catch {}
return { agentOutput, agentParsed, correctBookIds, coverUrls };
